function validate([sweetness, k]) {
  if (!Array.isArray(sweetness) || sweetness.length < 1 || sweetness.length > 10000) return 'sweetness needs 1 to 10^4 chunks.';
  if (sweetness.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each chunk has sweetness between 1 and 10^5.';
  if (!Number.isInteger(k) || k < 0 || k >= sweetness.length) return 'k is at least 0 and less than the number of chunks.';
  return null;
}

