function maximizeSweetness(sweetness, k) {
  const total = sweetness.reduce((sum, chunk) => sum + chunk, 0);
  let low = Math.min(...sweetness);
  let high = Math.floor(total / (k + 1));

  while (low < high) {
    const mid = Math.floor((low + high + 1) / 2);
    let pieces = 0;
    let current = 0;
    for (const chunk of sweetness) {
      current += chunk;
      if (current >= mid) {
        pieces++;
        current = 0;
      }
    }
    if (pieces >= k + 1) {
      low = mid;
    } else {
      high = mid - 1;
    }
  }
  return low;
}

