function maximizeSweetness(sweetness, k) {
  // best[i]: the largest possible smallest piece when the first i chunks form p pieces.
  const n = sweetness.length;
  const prefix = [0];
  for (const s of sweetness) prefix.push(prefix[prefix.length - 1] + s);
  let best = new Array(n + 1).fill(-Infinity);
  best[0] = Infinity;
  for (let p = 1; p <= k + 1; p++) {
    const next = new Array(n + 1).fill(-Infinity);
    for (let i = p; i <= n; i++)
      for (let j = p - 1; j < i; j++)
        if (best[j] !== -Infinity) next[i] = Math.max(next[i], Math.min(best[j], prefix[i] - prefix[j]));
    best = next;
  }
  return best[n];
}

