function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const n = 2000;
    const top = rand() < 0.5 ? 100000 : int(1, 100);
    const sweetness = Array.from({ length: n }, () => int(1, top));
    const shape = rand();
    const k = shape < 0.3 ? int(0, 10) : shape < 0.7 ? int(0, n - 1) : int(n - 50, n - 1);
    return [sweetness, k];
  }
  const n = int(1, 10);
  const top = rand() < 0.2 ? 100000 : int(1, 10);
  const sweetness = Array.from({ length: n }, () => int(1, top));
  return [sweetness, int(0, n - 1)];
}
